CREATE TABLE call_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),location_id uuid NOT NULL REFERENCES provider_locations(id),actor_id text NOT NULL,category text NOT NULL CHECK(category IN ('basic','availability','clinical','treatment_financial','transfer','other')),duration_minutes integer CHECK(duration_minutes BETWEEN 0 AND 600),had_prior_information boolean,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE analytics_events (event_id uuid PRIMARY KEY,session_id uuid NOT NULL,search_id uuid,location_id uuid REFERENCES provider_locations(id),event_type text NOT NULL CHECK(event_type IN ('search_started','result_impression','call_intent','directions_opened','intake_started','intake_submitted','intake_acknowledged','arrival_confirmed_by_staff','filter_changed','no_match_shown')),filters jsonb NOT NULL DEFAULT '{}'::jsonb,demo boolean NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX analytics_location_time_idx ON analytics_events(location_id,created_at);
CREATE TABLE partnerships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),location_id uuid NOT NULL UNIQUE REFERENCES provider_locations(id),stage text NOT NULL DEFAULT 'prospect' CHECK(stage IN ('prospect','contacted','discovery','agreed_pilot','onboarding','active_pilot','review','paying','paused','declined')),notes text,champion text,decision_maker text,next_follow_up date,existing_software text,integration_feasibility text,baseline_notes text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE pilot_agreements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),partnership_id uuid NOT NULL REFERENCES partnerships(id),activation_date date NOT NULL,review_date date NOT NULL,end_date date NOT NULL,proposed_price_cents integer CHECK(proposed_price_cents>=0),extension_reason text,conversion_agreed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
